BEGIN;
CREATE TABLE IF NOT EXISTS intake_item_revisions (item_id text NOT NULL REFERENCES intake_items(id) ON DELETE CASCADE, revision integer NOT NULL, snapshot jsonb NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(item_id,revision));
ALTER TABLE money_entries ADD COLUMN IF NOT EXISTS category text;
ALTER TABLE money_entries ADD COLUMN IF NOT EXISTS counterparty text;
ALTER TABLE money_entries ADD COLUMN IF NOT EXISTS source_id text REFERENCES sources(id);
CREATE TABLE IF NOT EXISTS purchases (id text PRIMARY KEY, subject_id text NOT NULL REFERENCES principals(id), merchant text NOT NULL, amount numeric(24,6) NOT NULL CHECK(amount>0), currency text NOT NULL, category text, occurred_on date NOT NULL, occurred_at timestamptz, time_zone text NOT NULL, note text, source_id text REFERENCES sources(id), revision integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS purchase_items (id text PRIMARY KEY, purchase_id text NOT NULL REFERENCES purchases(id) ON DELETE CASCADE, position integer NOT NULL, name text NOT NULL, quantity numeric(24,6), unit_price numeric(24,6), UNIQUE(purchase_id,position));
CREATE TABLE IF NOT EXISTS refunds (id text PRIMARY KEY, subject_id text NOT NULL REFERENCES principals(id), original_entry_id text NOT NULL REFERENCES money_entries(id), refund_entry_id text NOT NULL REFERENCES money_entries(id), revision integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS budgets (id text PRIMARY KEY, subject_id text NOT NULL REFERENCES principals(id), period text NOT NULL, category text NOT NULL, amount numeric(24,6) NOT NULL CHECK(amount>0), currency text NOT NULL, revision integer NOT NULL DEFAULT 1, UNIQUE(subject_id,period,category));
CREATE TABLE IF NOT EXISTS recurring_plans (id text PRIMARY KEY, subject_id text NOT NULL REFERENCES principals(id), title text NOT NULL, amount numeric(24,6) NOT NULL CHECK(amount>0), currency text NOT NULL, cadence text NOT NULL, next_due_on date NOT NULL, category text, active boolean NOT NULL, revision integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS health_measurements (id text PRIMARY KEY, subject_id text NOT NULL REFERENCES principals(id), metric text NOT NULL, value numeric(24,6) NOT NULL, unit text NOT NULL, label text, occurred_on date NOT NULL, occurred_at timestamptz, time_zone text NOT NULL, note text, source_id text REFERENCES sources(id), revision integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS trips (id text PRIMARY KEY, subject_id text NOT NULL REFERENCES principals(id), title text NOT NULL, starts_on date NOT NULL, ends_on date NOT NULL CHECK(ends_on>=starts_on), time_zone text NOT NULL, note text, revision integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS reservations (id text PRIMARY KEY, subject_id text NOT NULL REFERENCES principals(id), trip_id text NOT NULL REFERENCES trips(id) ON DELETE CASCADE, reservation_type text NOT NULL, title text NOT NULL, starts_at timestamptz, ends_at timestamptz, confirmation_code text, source_id text REFERENCES sources(id), revision integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS visits (id text PRIMARY KEY, subject_id text NOT NULL REFERENCES principals(id), trip_id text REFERENCES trips(id), place_name text NOT NULL, latitude numeric(10,7), longitude numeric(10,7), occurred_on date NOT NULL, occurred_at timestamptz, time_zone text NOT NULL, note text, source_id text REFERENCES sources(id), revision integer NOT NULL DEFAULT 1, CHECK((latitude IS NULL)=(longitude IS NULL)));
CREATE TABLE IF NOT EXISTS library_items (id text PRIMARY KEY, subject_id text NOT NULL REFERENCES principals(id), title text NOT NULL, item_type text NOT NULL, current_revision integer NOT NULL DEFAULT 1, source_id text REFERENCES sources(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS library_revisions (item_id text NOT NULL REFERENCES library_items(id) ON DELETE CASCADE, revision integer NOT NULL, text text, url text, tags jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(item_id,revision));
CREATE INDEX IF NOT EXISTS library_revisions_search_idx ON library_revisions USING gin(to_tsvector('simple',coalesce(text,'')));
CREATE TABLE IF NOT EXISTS threads (id text PRIMARY KEY, subject_id text NOT NULL REFERENCES principals(id), title text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS messages (id text PRIMARY KEY, thread_id text NOT NULL REFERENCES threads(id) ON DELETE CASCADE, role text NOT NULL, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS runs (id text PRIMARY KEY, thread_id text NOT NULL REFERENCES threads(id) ON DELETE CASCADE, status text NOT NULL, error text, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
CREATE TABLE IF NOT EXISTS run_events (run_id text NOT NULL REFERENCES runs(id) ON DELETE CASCADE, sequence integer NOT NULL, event_type text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(run_id,sequence));
COMMIT;
